const cfg = $("Set Wiki Audit Config").first().json;
const staleDays = Number(cfg.staleAfterDays) || 90;
const thinWords = Number(cfg.thinWordCount) || 120;
const orphanWeight = Number(cfg.orphanWeight) || 3;
const staleWeight = Number(cfg.staleWeight) || 2;
const thinWeight = Number(cfg.thinWeight) || 1;
const brokenWeight = Number(cfg.brokenLinkWeight) || 2;
const fetchFailedWeight = 1;

const pages = $input.all().map(item => item.json).filter(p => p && p.pageId);
const known = new Set(pages.map(p => p.pageId));

const inbound = new Map();
const brokenByPage = new Map();
for (const p of pages) inbound.set(p.pageId, 0);

for (const p of pages) {
  const broken = [];
  for (const target of p.outboundLinks || []) {
    if (known.has(target)) inbound.set(target, (inbound.get(target) || 0) + 1);
    else broken.push(target);
  }
  brokenByPage.set(p.pageId, broken);
}

const now = Date.now();
const auditedAt = new Date(now).toISOString();

const rows = pages.map(p => {
  const edited = p.lastEditedTime ? new Date(p.lastEditedTime).getTime() : null;
  const daysSinceEdit = edited ? Math.floor((now - edited) / 86400000) : null;
  const inboundLinks = inbound.get(p.pageId) || 0;
  const broken = brokenByPage.get(p.pageId) || [];
  // A page the integration could not read has no usable body, so the orphan and
  // thin thresholds would only be measuring the failed fetch. Flag the failure
  // and skip both checks. Stale still applies, last_edited_time comes from the
  // page search rather than the blocks.
  const fetchFailed = !!p.fetchFailed;
  const isOrphan = !fetchFailed && inboundLinks === 0;
  const isStale = daysSinceEdit !== null && daysSinceEdit >= staleDays;
  const isThin = !fetchFailed && Number(p.wordCount || 0) < thinWords;
  const score = (fetchFailed ? fetchFailedWeight : 0) + (isOrphan ? orphanWeight : 0) + (isStale ? staleWeight : 0) + (isThin ? thinWeight : 0) + broken.length * brokenWeight;
  const flags = [];
  if (fetchFailed) flags.push("Fetch failed");
  if (isOrphan) flags.push("Orphan");
  if (isStale) flags.push("Stale");
  if (isThin) flags.push("Thin");
  if (broken.length) flags.push("Unreachable mentions");
  return {
    pageId: p.pageId,
    title: p.title || "Untitled",
    url: p.url || "",
    status: flags.length ? flags.join(", ") : "Healthy",
    isOrphan: isOrphan,
    isStale: isStale,
    isThin: isThin,
    wordCount: Number(p.wordCount || 0),
    inboundLinks: inboundLinks,
    outboundLinkCount: (p.outboundLinks || []).length,
    brokenLinkCount: broken.length,
    brokenLinkTargets: broken.join(", "),
    daysSinceEdit: daysSinceEdit,
    lastEditedTime: p.lastEditedTime || null,
    score: score,
    fetchFailed: fetchFailed,
    auditedAt: auditedAt
  };
});

const totals = {
  totalPages: rows.length,
  orphanCount: rows.filter(r => r.isOrphan).length,
  staleCount: rows.filter(r => r.isStale).length,
  thinCount: rows.filter(r => r.isThin).length,
  brokenLinkPages: rows.filter(r => r.brokenLinkCount > 0).length,
  healthyCount: rows.filter(r => r.score === 0).length
};

rows.sort((a, b) => b.score - a.score);
return rows.map(r => ({ json: Object.assign({}, r, totals) }));

const cfg = $("Set Wiki Audit Config").first().json;
const keyProperty = cfg.pageIdPropertyName || "Page ID";
const findings = $("Filter Pages Needing Review").all().map(item => item.json);
const existing = $input.all().map(item => item.json);

function plainText(prop) {
  if (!prop) return "";
  const runs = prop.rich_text || prop.title || [];
  return runs.map(run => run.plain_text || "").join("").trim();
}

const rowByPageId = new Map();
for (const row of existing) {
  const value = plainText((row.properties || {})[keyProperty]);
  if (value) rowByPageId.set(value.toLowerCase(), row.id);
}

return findings.map(finding => ({
  json: Object.assign({}, finding, {
    healthRowId: rowByPageId.get(String(finding.pageId || "").toLowerCase()) || ""
  })
}));

const page = $("Loop Over Wiki Pages").first().json;
const raw = $input.all().map(item => item.json);
const blocks = raw.filter(b => b && b.type && !b.error);
const fetchFailed = raw.some(b => b && b.error);

const UUID_DASH = /[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/;
const HEX32 = /[0-9a-fA-F]{32}/;
const URL_RE = /https?:\/\/[^\s)\]]+/g;

function normalise(value) {
  const hex = String(value || "").replace(/-/g, "").toLowerCase();
  if (hex.length !== 32) return null;
  return hex.slice(0, 8) + "-" + hex.slice(8, 12) + "-" + hex.slice(12, 16) + "-" + hex.slice(16, 20) + "-" + hex.slice(20);
}

function idFromUrl(value) {
  const url = String(value || "");
  if (!/notion\.(so|site)/i.test(url)) return null;
  const match = url.match(UUID_DASH) || url.match(HEX32);
  return match ? normalise(match[0]) : null;
}

function pageTitle(source) {
  const props = source.properties || {};
  for (const key of Object.keys(props)) {
    const prop = props[key];
    if (prop && prop.type === "title" && Array.isArray(prop.title)) {
      const text = prop.title.map(run => run.plain_text || "").join("").trim();
      if (text) return text;
    }
  }
  return "Untitled";
}

const links = new Set();
let words = 0;

function readRichText(runs) {
  for (const run of runs || []) {
    const text = run.plain_text != null ? run.plain_text : ((run.text && run.text.content) || "");
    if (text) words += text.split(/\s+/).filter(Boolean).length;
    if (run.type === "mention" && run.mention && run.mention.type === "page" && run.mention.page) {
      const mentioned = normalise(run.mention.page.id);
      if (mentioned) links.add(mentioned);
    }
    const href = run.href || (run.text && run.text.link && run.text.link.url) || "";
    const linked = idFromUrl(href);
    if (linked) links.add(linked);
    for (const found of text.match(URL_RE) || []) {
      const pasted = idFromUrl(found);
      if (pasted) links.add(pasted);
    }
  }
}

for (const block of blocks) {
  if (block.type === "child_page") {
    const child = normalise(block.id);
    if (child) links.add(child);
    continue;
  }
  if (block.type === "link_to_page" && block.link_to_page && block.link_to_page.page_id) {
    const target = normalise(block.link_to_page.page_id);
    if (target) links.add(target);
  }
  const body = block[block.type];
  if (!body || typeof body !== "object") continue;
  if (Array.isArray(body.rich_text)) readRichText(body.rich_text);
  if (Array.isArray(body.caption)) readRichText(body.caption);
  if (Array.isArray(body.cells)) for (const cell of body.cells) readRichText(cell);
}

const self = normalise(page.id);
links.delete(self);

return [{ json: {
  pageId: self,
  title: pageTitle(page),
  url: page.url || "",
  lastEditedTime: page.last_edited_time || null,
  wordCount: words,
  outboundLinks: Array.from(links),
  blockCount: blocks.length,
  fetchFailed: fetchFailed
} }];

const cfg = $("Set Wiki Audit Config").first().json;
const digestSize = Number(cfg.digestSize) || 10;
const rows = $input.all().map(item => item.json);
const totals = rows[0] || {};

const flagged = rows
  .filter(r => Number(r.score || 0) > 0)
  .sort((a, b) => (b.score - a.score) || (b.brokenLinkCount - a.brokenLinkCount));
const top = flagged.slice(0, digestSize);

const lines = top.map((r, index) => {
  const bits = ["score " + r.score];
  if (r.fetchFailed) bits.push("could not be read, check integration access");
  if (r.isOrphan) bits.push("no inbound links");
  if (r.isStale) bits.push(r.daysSinceEdit + " days since edit");
  if (r.isThin) bits.push(r.wordCount + " words");
  if (r.brokenLinkCount) bits.push(r.brokenLinkCount + " unreachable mentions");
  const label = r.url ? "<" + r.url + "|" + (r.title || "Untitled") + ">" : (r.title || "Untitled");
  return (index + 1) + ". " + label + " - " + bits.join(", ");
});

const header = "*Wiki health sweep* " + String(totals.auditedAt || "").slice(0, 10)
  + "\n" + (totals.totalPages || 0) + " pages audited, " + (totals.healthyCount || 0) + " healthy, " + flagged.length + " need attention"
  + "\nOrphan " + (totals.orphanCount || 0) + "  |  Stale " + (totals.staleCount || 0) + "  |  Thin " + (totals.thinCount || 0) + "  |  Unreachable mentions on " + (totals.brokenLinkPages || 0) + " pages";

const body = lines.length
  ? "\n\n*Worst offenders*\n" + lines.join("\n")
  : "\n\nNothing crossed a threshold this week.";

return [{ json: { digest: header + body, flaggedCount: flagged.length, rankedCount: top.length } }];
